/* Hidden attribute support */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #2b213a;
  --card-bg: #fff8f0;
  --primary: #5c3c92;
  --primary-hover: #452b71;
  --accent: #e07a5f;
  --accent-hover: #cb6144;
  --adopted-badge: #4e8752;
  --text-main: #2b213a;
  --text-muted: #5e546b;
  --border-color: #e5d5c5;
  --shadow: 0 8px 24px rgba(0, 0, 0, 0.25);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text-main);
  background-color: var(--bg-color);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 24px 16px;
}

.shelter-card {
  background-color: var(--card-bg);
  width: 100%;
  max-width: 800px;
  border-radius: 16px;
  box-shadow: var(--shadow);
  padding: 28px 24px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.shelter-header {
  text-align: center;
}

.title {
  font-size: 2rem;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 4px;
  letter-spacing: -0.5px;
}

.subtitle {
  font-size: 1rem;
  color: var(--text-muted);
}

.stats-panel {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.stat-badge {
  background: #f0e6da;
  border: 2px solid var(--border-color);
  padding: 10px 20px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
}

.stat-label {
  color: var(--text-muted);
}

.stat-value {
  font-size: 1.25rem;
  color: var(--primary);
  font-weight: 800;
}

.filters-section {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.filter-label {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-muted);
}

.filter-group {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
}

button {
  font-family: inherit;
  font-size: 1rem;
  cursor: pointer;
  border: none;
  outline: none;
  transition: background-color 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.filter-btn {
  padding: 8px 16px;
  border-radius: 8px;
  background-color: #f0e6da;
  color: var(--text-main);
  font-weight: 600;
  border: 2px solid var(--border-color);
}

.filter-btn:hover {
  background-color: #e4d7c7;
}

.filter-btn:active {
  transform: translateY(1px);
}

.filter-btn.active {
  background-color: var(--primary);
  color: #ffffff;
  border-color: var(--primary);
}

.section-title {
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--primary);
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 8px;
  margin-bottom: 16px;
}

.pet-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 16px;
}

.pet-card {
  background: #ffffff;
  border: 2px solid var(--border-color);
  border-radius: 12px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 12px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.05);
}

.pet-card.adopted {
  background: #f9fbf9;
  border-color: #c9decb;
  opacity: 0.95;
}

.pet-canvas {
  image-rendering: pixelated;
  background: #f7f3ee;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  width: 96px;
  height: 96px;
}

.pet-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 100%;
}

.pet-name {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-main);
}

.pet-detail {
  font-size: 0.95rem;
  color: var(--text-muted);
}

.adopt-btn {
  width: 100%;
  padding: 10px 16px;
  border-radius: 8px;
  background-color: var(--accent);
  color: #ffffff;
  font-weight: 700;
  margin-top: 4px;
}

.adopt-btn:hover {
  background-color: var(--accent-hover);
}

.adopt-btn:active {
  transform: translateY(1px);
}

.status-tag {
  display: inline-block;
  width: 100%;
  padding: 8px 12px;
  border-radius: 8px;
  background-color: #e5f4e7;
  color: var(--adopted-badge);
  font-weight: 700;
  font-size: 0.95rem;
  margin-top: 4px;
}

.empty-msg {
  color: var(--text-muted);
  font-style: italic;
  text-align: center;
  padding: 16px;
}

@media (max-width: 480px) {
  .shelter-card {
    padding: 20px 14px;
    border-radius: 12px;
  }

  .pet-grid {
    grid-template-columns: 1fr;
  }

  .title {
    font-size: 1.6rem;
  }
}

document.addEventListener("DOMContentLoaded", () => {
  const pets = [
    { id: 1, name: "Barnaby", species: "Cat", age: 2, adopted: false, color: "#d97736" },
    { id: 2, name: "Mochi", species: "Cat", age: 1, adopted: false, color: "#4a4e69" },
    { id: 3, name: "Rusty", species: "Dog", age: 4, adopted: false, color: "#9a6324" },
    { id: 4, name: "Buster", species: "Dog", age: 3, adopted: false, color: "#e0a96d" },
    { id: 5, name: "Clover", species: "Bunny", age: 1, adopted: false, color: "#ece4db" },
    { id: 6, name: "Pepper", species: "Bunny", age: 2, adopted: false, color: "#6c757d" }
  ];

  let currentFilter = "All";

  const availableListEl = document.getElementById("available-pets-list");
  const adoptedListEl = document.getElementById("adopted-pets-list");
  const availableCountEl = document.getElementById("available-count");
  const adoptedCountEl = document.getElementById("adopted-count");
  const noPetsMsgEl = document.getElementById("no-pets-msg");
  const noAdoptedMsgEl = document.getElementById("no-adopted-msg");
  const filterButtonsContainer = document.getElementById("filter-buttons");

  function drawPixelPet(canvas, species, bodyColor) {
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const size = 16;
    const pixelSize = canvas.width / size;

    function fillPx(x, y, color) {
      ctx.fillStyle = color;
      ctx.fillRect(x * pixelSize, y * pixelSize, pixelSize, pixelSize);
    }

    const eyeColor = "#1a1a1a";
    const noseColor = "#e76f51";
    const innerEar = "#f4a261";

    if (species === "Cat") {
      // Ears
      for (let x = 3; x <= 5; x++) for (let y = 3; y <= 5; y++) fillPx(x, y, bodyColor);
      for (let x = 10; x <= 12; x++) for (let y = 3; y <= 5; y++) fillPx(x, y, bodyColor);
      fillPx(4, 4, innerEar);
      fillPx(11, 4, innerEar);
      // Head
      for (let x = 3; x <= 12; x++) for (let y = 5; y <= 11; y++) fillPx(x, y, bodyColor);
      // Eyes
      fillPx(5, 7, eyeColor);
      fillPx(10, 7, eyeColor);
      // Nose & Mouth
      fillPx(7, 9, noseColor);
      fillPx(8, 9, noseColor);
      // Whiskers
      fillPx(2, 9, "#ffffff");
      fillPx(13, 9, "#ffffff");
      // Body
      for (let x = 4; x <= 11; x++) for (let y = 12; y <= 14; y++) fillPx(x, y, bodyColor);
    } else if (species === "Dog") {
      // Floppy Ears
      for (let x = 2; x <= 4; x++) for (let y = 4; y <= 8; y++) fillPx(x, y, "#593a1c");
      for (let x = 11; x <= 13; x++) for (let y = 4; y <= 8; y++) fillPx(x, y, "#593a1c");
      // Head
      for (let x = 4; x <= 11; x++) for (let y = 4; y <= 11; y++) fillPx(x, y, bodyColor);
      // Snout
      for (let x = 6; x <= 9; x++) for (let y = 8; y <= 10; y++) fillPx(x, y, "#ffffff");
      // Eyes
      fillPx(5, 6, eyeColor);
      fillPx(10, 6, eyeColor);
      // Nose & Tongue
      fillPx(7, 8, eyeColor);
      fillPx(8, 8, eyeColor);
      fillPx(7, 10, "#e63946");
      // Body
      for (let x = 4; x <= 11; x++) for (let y = 12; y <= 14; y++) fillPx(x, y, bodyColor);
    } else if (species === "Bunny") {
      // Long Ears
      for (let y = 1; y <= 6; y++) {
        fillPx(4, y, bodyColor);
        fillPx(5, y, innerEar);
        fillPx(10, y, innerEar);
        fillPx(11, y, bodyColor);
      }
      // Head
      for (let x = 3; x <= 12; x++) for (let y = 6; y <= 12; y++) fillPx(x, y, bodyColor);
      // Eyes
      fillPx(5, 8, eyeColor);
      fillPx(10, 8, eyeColor);
      // Cheeks
      fillPx(4, 9, "#f4a261");
      fillPx(11, 9, "#f4a261");
      // Nose
      fillPx(7, 9, noseColor);
      fillPx(8, 9, noseColor);
      // Body
      for (let x = 4; x <= 11; x++) for (let y = 13; y <= 14; y++) fillPx(x, y, bodyColor);
    }
  }

  function render() {
    const availablePets = pets.filter(p => !p.adopted);
    const adoptedPets = pets.filter(p => p.adopted);

    availableCountEl.textContent = availablePets.length;
    adoptedCountEl.textContent = adoptedPets.length;

    const filteredAvailable = availablePets.filter(p => {
      return currentFilter === "All" || p.species === currentFilter;
    });

    availableListEl.innerHTML = "";
    if (filteredAvailable.length === 0) {
      noPetsMsgEl.hidden = false;
    } else {
      noPetsMsgEl.hidden = true;
      filteredAvailable.forEach(pet => {
        const card = createPetCard(pet, false);
        availableListEl.appendChild(card);
      });
    }

    adoptedListEl.innerHTML = "";
    if (adoptedPets.length === 0) {
      noAdoptedMsgEl.hidden = false;
    } else {
      noAdoptedMsgEl.hidden = true;
      adoptedPets.forEach(pet => {
        const card = createPetCard(pet, true);
        adoptedListEl.appendChild(card);
      });
    }
  }

  function createPetCard(pet, isAdopted) {
    const card = document.createElement("article");
    card.className = `pet-card${isAdopted ? " adopted" : ""}`;
    card.setAttribute("aria-label", `${pet.name}, a ${pet.age} year old ${pet.species}`);

    const canvas = document.createElement("canvas");
    canvas.className = "pet-canvas";
    canvas.width = 64;
    canvas.height = 64;
    canvas.setAttribute("role", "img");
    canvas.setAttribute("aria-label", `Pixel art portrait of ${pet.name}`);
    drawPixelPet(canvas, pet.species, pet.color);

    const info = document.createElement("div");
    info.className = "pet-info";

    const name = document.createElement("h3");
    name.className = "pet-name";
    name.textContent = pet.name;

    const species = document.createElement("p");
    species.className = "pet-detail";
    species.textContent = `Species: ${pet.species}`;

    const age = document.createElement("p");
    age.className = "pet-detail";
    age.textContent = `Age: ${pet.age} ${pet.age === 1 ? "year" : "years"}`;

    info.appendChild(name);
    info.appendChild(species);
    info.appendChild(age);

    card.appendChild(canvas);
    card.appendChild(info);

    if (!isAdopted) {
      const adoptBtn = document.createElement("button");
      adoptBtn.type = "button";
      adoptBtn.className = "adopt-btn";
      adoptBtn.textContent = "Adopt";
      adoptBtn.setAttribute("aria-label", `Adopt ${pet.name}`);
      adoptBtn.addEventListener("click", () => {
        pet.adopted = true;
        render();
      });
      card.appendChild(adoptBtn);
    } else {
      const badge = document.createElement("span");
      badge.className = "status-tag";
      badge.textContent = "Adopted ❤️";
      card.appendChild(badge);
    }

    return card;
  }

  filterButtonsContainer.addEventListener("click", (e) => {
    const btn = e.target.closest(".filter-btn");
    if (!btn) return;

    currentFilter = btn.dataset.filter;

    const buttons = filterButtonsContainer.querySelectorAll(".filter-btn");
    buttons.forEach(b => {
      const isActive = b === btn;
      b.classList.toggle("active", isActive);
      b.setAttribute("aria-pressed", isActive ? "true" : "false");
    });

    render();
  });

  render();
});
